begin;
create table public.technical_book_units (
 id uuid primary key default gen_random_uuid(),
 hotel_id uuid not null references public.hotels(id),
 book_id text not null check(book_id in ('extintores','bie')),
 source_key text not null default gen_random_uuid()::text,
 code text not null check(length(trim(code)) between 1 and 50),
 name text not null check(length(trim(name)) between 1 and 200),
 equipment_id uuid not null references public.apparatus_registry(id),
 location_id uuid references public.hotel_locations(id),
 metadata jsonb not null default '{}'::jsonb check(jsonb_typeof(metadata)='object'),
 active boolean not null default true,
 verified boolean not null default false,
 updated_at timestamptz not null default now(),
 unique(hotel_id,book_id,source_key)
);
alter table public.technical_book_units enable row level security;
revoke all on public.technical_book_units from public,anon,authenticated;
grant select,insert,update on public.technical_book_units to authenticated;
create policy book_units_read on public.technical_book_units for select to authenticated
using(public.has_hotel_permission(hotel_id,'maintenance.view'));
create policy book_units_create on public.technical_book_units for insert to authenticated
with check(auth.uid()<>'6d755017-7348-41ea-aad7-d1b8334fff99' and public.has_hotel_permission(hotel_id,'maintenance.update'));
create policy book_units_update on public.technical_book_units for update to authenticated
using(auth.uid()<>'6d755017-7348-41ea-aad7-d1b8334fff99' and public.has_hotel_permission(hotel_id,'maintenance.update'))
with check(auth.uid()<>'6d755017-7348-41ea-aad7-d1b8334fff99' and public.has_hotel_permission(hotel_id,'maintenance.update'));

create function public.validate_book_unit() returns trigger
language plpgsql security invoker set search_path=pg_catalog,public as $$
begin
 if exists(select 1 from jsonb_each(new.metadata) item where jsonb_typeof(item.value)<>'string' or length(item.value#>>'{}')>3000) then
  raise exception 'Los datos de placa, tipo y señalización deben ser texto.';
 end if;
 if tg_op='UPDATE' and (new.hotel_id,new.book_id,new.id,new.source_key) is distinct from (old.hotel_id,old.book_id,old.id,old.source_key) then
  raise exception 'No se puede cambiar la identidad de una unidad.';
 end if;
 if not exists(select 1 from public.apparatus_registry where id=new.equipment_id and hotel_id=new.hotel_id)
 or (new.location_id is not null and not exists(select 1 from public.hotel_locations where id=new.location_id and hotel_id=new.hotel_id)) then
  raise exception 'El activo y la ubicación deben pertenecer al hotel.';
 end if;
 if new.verified and (new.location_id is null or not exists(select 1 from public.hotel_locations where id=new.location_id and active)) then
  raise exception 'Selecciona una ubicación activa antes de confirmar la unidad.';
 end if;
 new.updated_at:=now();
 return new;
end $$;
revoke all on function public.validate_book_unit() from public,anon,authenticated;
create trigger book_units_validate before insert or update on public.technical_book_units for each row execute function public.validate_book_unit();

-- Reuse the hotel's configured rooms and the inventory's exact floor/zone names.
do $$
declare
 hotel constant uuid := '9e2e3d56-25d7-41a5-8dd6-df6858e735bd';
 root_id uuid; floor_id uuid; zone_id uuid; item record; floor_code text;
begin
 if not exists(select 1 from public.hotels where id=hotel) then return; end if;
 insert into public.hotel_locations(hotel_id,location_type,code,name,sort_order)
 values(hotel,'ZONA','HOTEL','Hotel',0) on conflict do nothing;
 select id into strict root_id from public.hotel_locations where hotel_id=hotel and code='HOTEL';
 for item in
  select distinct plant code from public.apparatus_registry where hotel_id=hotel and plant ~ '^P-?[0-9]+$'
  union
  select distinct 'P'||lpad(split_part(room_code,'-',1),2,'0') from public.maintenance_room_fancoil_tracking where hotel_id=hotel
 loop
  insert into public.hotel_locations(hotel_id,parent_location_id,location_type,code,name,sort_order)
  values(hotel,root_id,'PLANTA',item.code,'Planta '||substring(item.code from 2)::integer,(substring(item.code from 2)::integer+3)*10)
  on conflict do nothing;
 end loop;
 for item in select distinct coalesce(plant,'HOTEL') plant,coalesce(nullif(trim(location),''),'Ámbito del hotel') zone
 from public.apparatus_registry where hotel_id=hotel loop
  select id into strict floor_id from public.hotel_locations where hotel_id=hotel and code=item.plant;
  insert into public.hotel_locations(hotel_id,parent_location_id,location_type,code,name)
  values(hotel,floor_id,'ZONA','INV:'||item.plant||':'||item.zone,item.zone) on conflict do nothing;
  select id into strict zone_id from public.hotel_locations where hotel_id=hotel and code='INV:'||item.plant||':'||item.zone;
  update public.apparatus_registry set location_id=zone_id
  where hotel_id=hotel and location_id is null and coalesce(plant,'HOTEL')=item.plant
    and coalesce(nullif(trim(location),''),'Ámbito del hotel')=item.zone;
 end loop;
 for item in select room_code from public.maintenance_room_fancoil_tracking where hotel_id=hotel order by room_code loop
  floor_code:='P'||lpad(split_part(item.room_code,'-',1),2,'0');
  select id into strict floor_id from public.hotel_locations where hotel_id=hotel and code=floor_code;
  insert into public.hotel_locations(hotel_id,parent_location_id,location_type,code,name,sort_order)
  values(hotel,floor_id,'HABITACION',item.room_code,'Habitación '||item.room_code,split_part(item.room_code,'-',2)::integer)
  on conflict do nothing;
 end loop;
end $$;

create function public.book_location_path(target_id uuid) returns text
language sql stable security invoker set search_path=pg_catalog,public as $$
 with recursive ancestors as (
  select id,parent_location_id,name,0 depth,array[id] visited from public.hotel_locations where id=target_id
  union all
  select l.id,l.parent_location_id,l.name,a.depth+1,a.visited||l.id from public.hotel_locations l
  join ancestors a on l.id=a.parent_location_id where not l.id=any(a.visited)
 ) select string_agg(name,' / ' order by depth desc) from ancestors
$$;
revoke all on function public.book_location_path(uuid) from public,anon;
grant execute on function public.book_location_path(uuid) to authenticated;

create function public.stamp_book_catalog_target() returns trigger
language plpgsql security invoker set search_path=pg_catalog,public as $$
declare
 p jsonb:=new.payload; asset public.apparatus_registry; place public.hotel_locations;
 unit public.technical_book_units; label text; target text; control_labels jsonb; campaign_target record;
begin
 if tg_op='UPDATE' and old.payload->>'status'='FINAL' then return new; end if;
 if new.book_id in ('pool','spa') then return new; end if;
 if new.book_id='pci' and new.hotel_id='9e2e3d56-25d7-41a5-8dd6-df6858e735bd' then
  p:=jsonb_set(p,'{answers,control-B36}',jsonb_build_object('value','NA','note','La megafonía del hotel se utiliza para música.'));
 end if;
 if nullif(p->>'unitId','') is not null then
  select * into unit from public.technical_book_units where id=(p->>'unitId')::uuid and hotel_id=new.hotel_id and book_id=new.book_id and active;
  if not found then raise exception 'Selecciona una unidad activa del catálogo del hotel.'; end if;
  p:=p||jsonb_build_object('assetId',unit.equipment_id,'locationId',unit.location_id);
  label:=unit.code||' · '||unit.name; target:='unit:'||unit.id;
 elsif nullif(p->>'assetId','') is not null then
  select * into asset from public.apparatus_registry where id=(p->>'assetId')::uuid and hotel_id=new.hotel_id and active;
  if not found then raise exception 'Selecciona un activo del catálogo del hotel.'; end if;
  p:=p||jsonb_build_object('locationId',asset.location_id);
  label:=coalesce(asset.source_id::text,asset.code)||' · '||asset.name||
   case when exists(select 1 from public.apparatus_registry a where a.hotel_id=new.hotel_id and a.active and a.id<>asset.id and a.source_id=asset.source_id and a.name=asset.name)
    then ' · '||asset.code else '' end;
  target:='asset:'||asset.id;
 else
  target:='location:'||coalesce(p->>'locationId','');
 end if;
 select * into place from public.hotel_locations where id=nullif(p->>'locationId','')::uuid and hotel_id=new.hotel_id and active;
 if not found then raise exception 'Selecciona una ubicación activa del catálogo del hotel.'; end if;
 if new.book_id in ('fancoils','fondo-habitaciones','revision-habitaciones') then
  if place.location_type<>'HABITACION' or asset.id is not null or unit.id is not null then raise exception 'Selecciona una habitación del hotel.'; end if;
  label:=coalesce(place.code,place.name);
 elsif new.book_id in ('extintores','bie') and unit.id is null then
  raise exception 'Selecciona una unidad del listado de este libro.';
 end if;
 if nullif(p->>'pamTicketId','') is not null and asset.id is distinct from (
  select equipment_id from public.technical_book_due_tickets where ticket_id=(p->>'pamTicketId')::uuid and hotel_id=new.hotel_id and book_id=new.book_id
 ) then raise exception 'El ticket corresponde a otro activo.'; end if;
 p:=p-'controlEquipmentLabels';
 if p ? 'controlEquipmentIds' then
  if jsonb_typeof(p->'controlEquipmentIds')<>'object' then raise exception 'Equipos de los controles no válidos.'; end if;
  if exists(select 1 from jsonb_each_text(p->'controlEquipmentIds') c where c.value<>'' and (
   not exists(select 1 from public.apparatus_registry where id=c.value::uuid and hotel_id=new.hotel_id and active)
   or not exists(select 1 from jsonb_array_elements(p->'template'->'fields') f where f->>'id'=c.key)
  )) then raise exception 'Selecciona los equipos de los controles en el catálogo del hotel.'; end if;
  select coalesce(jsonb_object_agg(c.key,coalesce(a.source_id::text,a.code)||' · '||a.name),'{}'::jsonb) into control_labels
  from jsonb_each_text(p->'controlEquipmentIds') c join public.apparatus_registry a on a.id=nullif(c.value,'')::uuid and a.hotel_id=new.hotel_id;
  p:=p||jsonb_build_object('controlEquipmentLabels',control_labels);
 end if;
 if new.book_id='legionella' and p->>'status'='FINAL' and exists(
  select 1 from jsonb_each(p->'answers') a where a.key ~ '^activity-(9|1[0-8])$' and a.value->>'value' not in ('','NA')
  and nullif(p->'controlEquipmentIds'->>a.key,'') is null
 ) then raise exception 'Selecciona el acumulador del catálogo para cada lectura de temperatura.'; end if;
 if nullif(p->>'campaignTargetId','') is null and new.book_id in ('fancoils','extintores','bie','pci','rociadores') then
  select t.id,t.ticket_id into campaign_target from public.technical_book_campaign_targets t
  join public.technical_book_campaigns c on c.ticket_id=t.ticket_id and c.closed_at is null
  join public.maintenance_work_orders w on w.id=t.ticket_id and w.status in ('PENDING','IN_PROGRESS','IN_MANAGEMENT')
  where t.hotel_id=new.hotel_id and t.book_id=new.book_id and t.target_key=target and t.required
  and t.record_id is null and t.previous_confirmed_at is null and w.scheduled_date<=timezone('Europe/Madrid',now())::date
  order by w.scheduled_date,t.ticket_id limit 1;
  if found then p:=p||jsonb_build_object('campaignTargetId',campaign_target.id,'campaignTicketId',campaign_target.ticket_id); end if;
 end if;
 new.payload:=p||jsonb_build_object('targetKey',target,'asset',coalesce(label,place.name),'location',public.book_location_path(place.id));
 return new;
end $$;
revoke all on function public.stamp_book_catalog_target() from public,anon,authenticated;
create trigger a_book_catalog_target before insert or update on public.technical_book_records for each row execute function public.stamp_book_catalog_target();

