  values(hotel,parent_id,'UBICACION','PCI:'||(item->>'book')||':'||(item->>'row'),item->>'name','Ubicación procedente del listado histórico. Pendiente de comprobación física.')
  on conflict do nothing;
  select id into place from public.hotel_locations where hotel_id=hotel and parent_location_id=parent_id and lower(trim(name))=lower(trim(item->>'name'));
  insert into public.technical_book_units(hotel_id,book_id,source_key,code,name,equipment_id,location_id,metadata,verified)
  values(hotel,item->>'book','R-SSTT-01-12:'||(item->>'book')||':'||(item->>'row'),item->>'code',item->>'name',equipment,place,item->'metadata',false)
  on conflict(hotel_id,book_id,source_key) do nothing;
 end loop;
end $seed_units$;

commit;
